describe('Element Manager', () => {
    beforeEach(() => {
        cy.visit('https://the-internet.herokuapp.com/add_remove_elements/');
    });

    it('should add two elements and verify their presence', () => {
        cy.get('button[onclick="addElement()"]').click();
        cy.get('button[onclick="addElement()"]').click();
        cy.get('.added-manually').should('have.length', 2);
    });

    it('should delete one element and verify one remains', () => {
        cy.get('button[onclick="addElement()"]').click();
        cy.get('button[onclick="addElement()"]').click();
        cy.get('.added-manually').first().click();
        cy.get('.added-manually').should('have.length', 1);
    });
});
